from lib import *
S = SS('k101')
F1 = [['Ready 条件(探针失败)', '超时 5.1 秒,退出码 1'], ['jsonpath phase=Running', '0.2 秒'], ['探针通过后 Ready', '0.3 秒'], ['不存在的资源', '立刻 NotFound'], ['--for=create / delete', '3.5 秒 / 3.1 秒']]
F2 = [['wait Available', '0.2 秒返回'], ['rollout status', '20.0 秒才结束'], ['原因', '更新期间旧 Pod 让 Available 一直为 True'], ['rollout status 的进度', '1/3 → 2/3 → 旧副本终止']]
F3 = [['镜像拉不到', ''], ['progressDeadlineSeconds: 20', '21 秒后'], ['rollout status', 'exceeded its progress deadline,退出码 1'], ['Deployment 条件', 'Progressing=False / ProgressDeadlineExceeded'], ['旧副本', '仍 3 个可用']]
F4 = [['job/ok', 'complete 5.3 秒'], ['job/bad', 'complete 等满 10 秒超时'], ['job/bad', 'failed 0.1 秒']]
PANELS = [('f', 'flow', '就绪的判断'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("Pod slow 的就绪探针(cat /tmp/ready)一直失败:kubectl wait --for=condition=Ready --timeout=5s 等了 5.1 秒,退出码 1,error: timed out waiting for the condition on pods/slow;--for=jsonpath='{.status.phase}'=Running 0.2 秒就满足了(phase 已是 Running,Ready 条件还没好)。探针通过后再等 Ready 只要 0.3 秒。等一个不存在的 pod/nothing 立刻报 NotFound(0.0 秒,不等待);--for=create 等一个 3 秒后才创建的 ConfigMap 用了 3.5 秒;--for=delete 等 pod/slow 被删掉用了 3.1 秒。", f=fl(F1, cur=[0, 1, 4], done=[2, 3]), t=tl(S(1), mark=lidx(S(1), 'condition=Ready(探针一直失败)', '不存在的 pod/nothing'), done=lidx(S(1), '让探针通过后', '--for=create', '--for=delete')), kv=KV([['条件和字段', 'condition=Ready 看 Pod 条件,jsonpath 看任意字段'], ['不存在会立刻失败', '要等它出现用 --for=create'], ['超时退出码 1', '脚本里可以直接判断']], ['condition vs jsonpath'])),
    step("Deployment web(3 副本,maxSurge 1 / maxUnavailable 0,新 Pod 要约 5 秒才就绪)改模板触发滚动更新:kubectl wait --for=condition=Available 0.2 秒就返回了(退出码 0),因为更新过程中旧 Pod 一直在服务,Available 始终是 True;kubectl rollout status 等到 20.0 秒才结束,输出依次是 1 out of 3 new replicas have been updated…、2 out of 3 …、1 old replicas are pending termination…,最后 deployment \"web\" successfully rolled out。首次创建 3 副本时 rollout status 用了 10 秒,进度是 0/1/2 of 3 updated replicas are available。", f=fl(F2, cur=[1, 3], done=[0, 2]), t=tl(S(2), mark=lidx(S(2), 'kubectl wait --for=condition=Available', 'kubectl rollout status 等到'), done=lidx(S(2), 'successfully rolled out', 'Progressing 条件')), b=bars([['wait Available', 0.2, '0.2 s'], ['rollout status', 20.0, '20.0 s']], 20, done=[1], mark=[0]), kv=KV([['Available', '“至少有 minAvailable 个可用”,滚动中也成立'], ['rollout status', '要求全部新副本更新并可用、旧副本终止'], ['发布脚本', '用 rollout status 判断发布完成']], ['rollout status'])),
    step("把镜像改成拉不到的(progressDeadlineSeconds: 20):rollout status 21 秒后退出,退出码 1,输出 error: deployment \"web\" exceeded its progress deadline;Deployment 条件 Progressing=False、reason=ProgressDeadlineExceeded,而 Available 仍是 True,旧副本照常服务(availableReplicas=3、readyReplicas=3)。rollout undo 之后再 rollout status 又是 successfully rolled out。", f=fl(F3, cur=[1, 2], done=[3, 4]), t=tl(S(3), mark=lidx(S(3), '把镜像改成拉不到的'), done=lidx(S(3), 'Deployment 条件', 'rollout undo')), kv=KV([['progressDeadlineSeconds', '默认 600 秒,超时后 rollout status 返回失败'], ['卡住不影响旧副本', '服务不中断,只是新版本发不出去'], ['超时 ≠ 回滚', '不会自动 undo,需要人或流水线处理']], ['progressDeadlineSeconds'])),
    step("Job:--for=condition=complete job/ok 5.3 秒满足;--for=condition=complete job/bad(这个 Job 会失败)等满 10.0 秒超时,error: timed out waiting for the condition on jobs/bad——失败的 Job 永远不会 Complete;--for=condition=failed job/bad 0.1 秒满足。要同时处理成功和失败,需要同时等两个条件(或轮询)。", f=fl(F4, cur=[1], done=[0, 2]), t=tl(S(4), mark=lidx(S(4), 'job/bad(这个 Job 会失败)'), done=lidx(S(4), 'job/ok', 'condition=failed')), kv=KV([['Complete 与 Failed 互斥', '失败的 Job 不会 Complete'], ['只等 complete', '失败时要干等到超时'], ['CI 里', '用 timeout 兜底,并同时关注 failed']], ['Complete 与 Failed'])),
]
A = mkartk('k101', 101, 'Kubernetes,kubectl wait,rollout status,就绪,progressDeadlineSeconds,真实验证,动画演示',
    '在 kind 集群里实测怎么判断“就绪”:kubectl wait 的 condition=Ready(探针失败时 5 秒超时)与 jsonpath 字段、等不存在的资源立刻报错、--for=create / --for=delete;滚动更新时 wait --for=condition=Available 0.2 秒就返回而 rollout status 要等 20 秒到全部更新完成;镜像拉不到时 rollout status 在 progressDeadlineSeconds 之后以退出码 1 结束,旧副本仍在服务;失败的 Job 永远不会 Complete。',
    '发布脚本里该用 kubectl wait 还是 rollout status?Available 条件为什么在滚动更新中间就是 True?资源还不存在时 wait 会怎样?Job 失败了 wait 会不会一直卡住?这篇逐个量出来。',
    [('0.2 秒 vs 20 秒', '滚动更新期间 wait --for=condition=Available 与 rollout status 各自返回的时间'), ('21 秒', 'progressDeadlineSeconds=20 时,卡住的滚动更新 rollout status 以退出码 1 结束'), ('不会 Complete', '失败的 Job 永远不会有 Complete 条件,wait --for=condition=complete 只能干等到超时')],
    [('kubectl wait', '<p>Pod <code>slow</code> 的就绪探针一直失败:<code>kubectl wait --for=condition=Ready --timeout=5s</code> 等了 5.1 秒,退出码 1,<code>error: timed out waiting for the condition on pods/slow</code>;<code>--for=jsonpath=\'{.status.phase}\'=Running</code> 0.2 秒就满足(<code>phase</code> 已是 Running,<code>Ready</code> 条件还没好)。探针通过后再等 Ready 只要 0.3 秒。等一个不存在的 <code>pod/nothing</code> 立刻报 NotFound(不会等待);<code>--for=create</code> 等一个 3 秒后才创建的 ConfigMap 用了 3.5 秒;<code>--for=delete</code> 等 <code>pod/slow</code> 被删掉用了 3.1 秒。</p>'),
     ('Available 与 rollout status', '<p>Deployment <code>web</code>(3 副本,<code>maxSurge 1 / maxUnavailable 0</code>,新 Pod 要约 5 秒才就绪)改模板触发滚动更新:<code>kubectl wait --for=condition=Available</code> 0.2 秒就返回了,因为更新过程中旧 Pod 一直在服务,<code>Available</code> 始终是 True;<code>kubectl rollout status</code> 等到 20.0 秒才结束,输出依次是 <code>1 out of 3 new replicas have been updated…</code>、<code>2 out of 3 …</code>、<code>1 old replicas are pending termination…</code>,最后 <code>deployment "web" successfully rolled out</code>。判断“发布完成”要用 <code>rollout status</code>,不能用 <code>Available</code>。</p>'),
     ('卡住的发布', '<p>把镜像改成拉不到的(<code>progressDeadlineSeconds: 20</code>):<code>rollout status</code> 21 秒后退出,退出码 1,<code>error: deployment "web" exceeded its progress deadline</code>;Deployment 条件 <code>Progressing=False</code>、<code>reason=ProgressDeadlineExceeded</code>,而 <code>Available</code> 仍是 True,旧副本照常服务(<code>availableReplicas=3</code>)。超时不会自动回滚,<code>rollout undo</code> 之后再 <code>rollout status</code> 又是 <code>successfully rolled out</code>。</p>'),
     ('Job', '<p><code>--for=condition=complete job/ok</code> 5.3 秒满足;<code>--for=condition=complete job/bad</code>(这个 Job 会失败)等满 10.0 秒超时——失败的 Job 永远不会 <code>Complete</code>;<code>--for=condition=failed job/bad</code> 0.1 秒满足。要同时处理成功和失败,需要同时等两个条件或轮询,并总是设 <code>--timeout</code> 兜底。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0,kubectl 1.36);用时是 kubectl 进程的墙钟时间;Deployment 的新 Pod 就绪探针让每个新 Pod 约 5 秒后才就绪,所以更新总时长约 20 秒;--for=create 的 3 秒由另一个线程延迟创建;每种情形各一次',
     '没有验证:kubectl wait 对自定义资源 condition 的用法;--for=condition=Ready=false 的取反写法;kubectl rollout status 对 StatefulSet / DaemonSet 的判据;watch 超过 timeout 时的重连;kubectl wait 在资源被删除又重建时的行为;progressDeadlineSeconds 默认 600 秒的实际表现'],
    '就绪判断', PANELS)
